以下第24-30题基于以下程序：

```cpp
bool move(int b[], int n)
{
    for (int i = 0; i < n; ++i) {
        if (b[i] == 1) {
            b[i] = 0;
        }
        else {
            b[i] = 1;
            return true;
        }
    }
    return false;
}

void print(int n)
{
    int b[n];
    for (int i = 0; i < n; ++i) b[i] = 0;
    do {
        for (int i = 0; i < n; ++i) std::cout << b[i];
        std::cout << "\n";
    }
    while (move(b, n));
}

int count(int n)
{
    int b[100];
    for (int i = 0; i < n; ++i) b[i] = 0;
    int c = 0;
    do {
        c++;
    }
    while (move(b, n));
    return c;
}
```

当输入参数 n ∈ (0,20) 时，count 可能会陷入无尽的循环（ ）。

以下第31-37题基于以下程序：

```cpp
const int mod = 1'000'000'007;
bool filled[maxn][maxn];
int mem[maxn][maxn];

int solve(int i, int j, int a[], int b[])
{
    if (i == 0 || j == 0) {
        return 1;
    }
    if (filled[i][j]) {
        return mem[i][j];
    }
    filled[i][j] = true;
    int sum = (solve(i-1, j, a, b) + solve(i, j-1, a, b)) % mod;
    if (a[i] == b[j]) {
        return mem[i][j] = sum;
    }
    else {
        return mem[i][j] = (sum - solve(i-1, j-1, a, b)) % mod;
    }
}
```

若 a[1] = 1, a[2] = 3, b[1] = 3, b[2] = 1, solve(2, 2, a, b) 返回 3（ ）。

