以下第48-54题基于以下程序：

```cpp
#include<iostream>
void solve(int r, int b)
{
    int mem[1024] = {0};
    int q[1024] = {0};
    int step = 0;
    while (r != 0) {
        step++;
        if (mem[r] > 0) {
            break;
        }
        else {
            mem[r] = step;
        }
        q[step] = r * 2 / b;
        r = r * 2 % b;
    }
    std::cout << ".";
    if (r == 0) {
        for (int i = 1; i <= step; ++i) std::cout << q[i];
    }
    else {
        int begin = mem[r];
        for (int i = 1; i < begin; ++i)
            std::cout << q[i];
        std::cout << "(";
        for (int i = begin; i < step; ++i)
            std::cout << q[i];
        std::cout << ")";
    }
}
```

若输入参数 r = 0，程序会输出一个 0。

